"""Tests for the bulk discount feature."""

from decimal import Decimal

import pytest

from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)
from pricing.cart import Cart, LineItem


# --- tests/test_bulk_discount.py ---


class TestQualifiesForBulkDiscount:
    """Tests for qualifies_for_bulk_discount function."""

    def test_quantity_9_does_not_qualify(self):
        item = LineItem("apple", Decimal("1.00"), 9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-8764baca")
    def test_quantity_10_qualifies(self):
        item = LineItem("apple", Decimal("1.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_10_qualifies(self):
        item = LineItem("apple", Decimal("1.00"), 11)
        assert qualifies_for_bulk_discount(item) is True


class TestCalculateBulkDiscount:
    """Tests for calculate_bulk_discount function."""

    @pytest.mark.l4("C-1caf4da3")
    def test_non_qualifying_item_returns_zero(self):
        item = LineItem("apple", Decimal("10.00"), 9)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-8764baca")
    def test_qualifying_item_applies_5_percent_discount(self):
        item = LineItem("apple", Decimal("10.00"), 10)
        # 10 * 10.00 = 100.00, 5% of 100 = 5.00
        assert calculate_bulk_discount(item) == Decimal("5.00")

    @pytest.mark.l4("C-e4015f6b")
    def test_qualifying_item_with_quantity_11(self):
        item = LineItem("apple", Decimal("5.00"), 11)
        # 11 * 5.00 = 55.00, 5% of 55 = 2.75
        assert calculate_bulk_discount(item) == Decimal("2.75")

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding(self):
        # 10 * 0.025 = 0.25, 5% of 0.25 = 0.0125 -> rounds to 0.01
        item = LineItem("apple", Decimal("0.025"), 10)
        assert calculate_bulk_discount(item) == Decimal("0.01")

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding_2(self):
        # 10 * 0.035 = 0.35, 5% of 0.35 = 0.0175 -> rounds to 0.02
        item = LineItem("apple", Decimal("0.035"), 10)
        assert calculate_bulk_discount(item) == Decimal("0.02")


class TestCartBulkSavings:
    """Tests for Cart.bulk_savings method."""

    @pytest.mark.l4("C-cc0190d6")
    def test_empty_cart_returns_zero(self):
        cart = Cart()
        assert cart.bulk_savings() == Decimal("0.00")

    @pytest.mark.l4("C-efd8f9b2")
    def test_cart_with_no_qualifying_items_returns_zero(self):
        cart = Cart()
        cart.add(LineItem("apple", Decimal("10.00"), 5))
        cart.add(LineItem("pear", Decimal("5.00"), 3))
        assert cart.bulk_savings() == Decimal("0.00")

    @pytest.mark.l4("C-cc0190d6")
    def test_sum_of_qualifying_line_item_discounts(self):
        cart = Cart()
        cart.add(LineItem("apple", Decimal("10.00"), 10))  # 5% of 100 = 5.00
        cart.add(LineItem("pear", Decimal("5.00"), 11))   # 5% of 55 = 2.75
        assert cart.bulk_savings() == Decimal("7.75")

    @pytest.mark.l4("C-cc0190d6")
    def test_mixed_qualifying_and_non_qualifying_items(self):
        cart = Cart()
        cart.add(LineItem("apple", Decimal("10.00"), 9))  # 0.00
        cart.add(LineItem("pear", Decimal("10.00"), 10))  # 5.00
        cart.add(LineItem("banana", Decimal("5.00"), 11))  # 2.75
        assert cart.bulk_savings() == Decimal("7.75")


# --- tests/test_cart.py ---

